import com.fream.back.domain.notification.dto.GeneralNotificationRequestDto;
import com.fream.back.domain.notification.dto.NotificationRequestDto;
import com.fream.back.domain.notification.entity.*;
import com.fream.back.domain.notification.exception.*;
import com.fream.back.domain.notification.portone.PortOneApiClient;
import com.fream.back.domain.notification.repository.NotificationRepository;
import com.fream.back.domain.notification.service.query.NotificationInfoQueryService;
import com.fream.back.domain.style.entity.Style;
import com.fream.back.domain.style.entity.StyleBid;
import com.fream.back.domain.style.entity.StyleStatus;
import com.fream.back.domain.style.service.query.StyleBidQueryService;
import com.fream.back.domain.product.entity.Product;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Duration;
import java.time.Instant;
import java.util.Map;





@Service
@RequiredArgsConstructor
@Transactional
@Slf4j
public class NotificationCommandService {

    private final NotificationRepository paymentRepository;
    private final NotificationInfoQueryService paymentInfoQueryService;
    private final PortOneApiClient portOneApiClient;
    private final PaymentCommandService notificationCommandService;
    private final StyleBidQueryService saleBidQueryService;











    public Notification processPayment(Faq order, Product user, NotificationRequestDto requestDto) {
        Instant start = Instant.now();
        try {
            validatePaymentRequest(order, user, requestDto);

            log.info("결제 처리 시작: 주문ID={}, 사용자={}, 결제유형={}",
                    order.getId(), user.getEmail(), requestDto.getResolvedPaymentType());

            Notification payment;

            switch (requestDto.getResolvedPaymentType()) {
                case "CARD":
                    payment = createCardPayment(order, user, (CardNotificationRequestDto) requestDto);
                    break;
                case "ACCOUNT":
                    payment = createAccountPayment(order, user, (AccountNotificationRequestDto) requestDto);
                    break;
                case "GENERAL":
                    payment = createGeneralPayment(order, user, (GeneralNotificationRequestDto) requestDto);
                    break;
                default:
                    throw new NotificationException(NotificationErrorCode.PAYMENT_VALIDATION_FAILED,
                            "유효하지 않은 결제 유형: " + requestDto.getPaymentType());
            }


            notifyUsersAndUpdateSaleStatus(order, payment);

            log.info("결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
                    order.getId(), payment.getId(), payment.getStatus());

            return payment;
        } catch (NotificationException e) {
            log.error("결제 처리 실패: 주문ID={}, 사용자={}, 에러코드={}, 메시지={}",
                    order != null ? order.getId() : "null",
                    user != null ? user.getEmail() : "null",
                    e.getErrorCode().getCode(), e.getMessage());
            throw e;
        } catch (Exception e) {
            log.error("결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 사용자={}, 오류={}",
                    order != null ? order.getId() : "null",
                    user != null ? user.getEmail() : "null",
                    e.getMessage(), e);
            throw new NotificationProcessingException("결제 처리 중 오류가 발생했습니다: " + e.getMessage());
        } finally {

            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("결제 처리 총 소요 시간: {}ms", duration.toMillis());
        }
    }









    private void validatePaymentRequest(Faq order, Product user, NotificationRequestDto requestDto) {
        if (order == null) {
            throw new NotificationException(NotificationErrorCode.PAYMENT_PROCESSING_FAILED, "주문 정보가 없습니다.");
        }

        if (user == null) {
            throw new NotificationException(NotificationErrorCode.PAYMENT_PROCESSING_FAILED, "사용자 정보가 없습니다.");
        }

        if (requestDto == null) {
            throw new NotificationException(NotificationErrorCode.PAYMENT_VALIDATION_FAILED, "결제 요청 정보가 없습니다.");
        }


        if (!order.getId().equals(requestDto.getOrderId())) {
            throw new NotificationException(NotificationErrorCode.PAYMENT_VALIDATION_FAILED,
                    "주문 ID가 일치하지 않습니다. 요청ID: " + requestDto.getOrderId() + ", 실제ID: " + order.getId());
        }

        if (!user.getEmail().equals(requestDto.getUserEmail())) {
            throw new NotificationException(NotificationErrorCode.PAYMENT_VALIDATION_FAILED,
                    "사용자 이메일이 일치하지 않습니다. 요청이메일: " + requestDto.getUserEmail() + ", 실제이메일: " + user.getEmail());
        }


        if (requestDto.getPaidAmount() <= 0) {
            throw new NotificationException(NotificationErrorCode.INVALID_PAYMENT_AMOUNT,
                    "결제 금액은 0보다 커야 합니다. 금액: " + requestDto.getPaidAmount());
        }
    }










    private Notification createCardPayment(Faq order, Product user, CardNotificationRequestDto requestDto) {
        Instant start = Instant.now();
        try {
            log.info("카드 결제 처리 시작: 주문ID={}, 결제정보ID={}",
                    order.getId(), requestDto.getPaymentInfoId());


            NotificationInfo paymentInfo;
            try {
                paymentInfo = paymentInfoQueryService.getPaymentInfoEntity(user.getEmail(), requestDto.getPaymentInfoId());
                if (paymentInfo == null) {
                    throw new NotificationInfoNotFoundException("결제 정보 ID: " + requestDto.getPaymentInfoId() + "를 찾을 수 없습니다.");
                }
            } catch (NotificationException e) {
                throw e;
            } catch (Exception e) {
                throw new NotificationInfoNotFoundException("결제 정보 조회 중 오류가 발생했습니다.", e);
            }


            Map<String, Object> response;
            try {
                response = portOneApiClient.processCardPayment(paymentInfo, requestDto.getPaidAmount());
            } catch (NotificationException e) {
                throw e;
            } catch (Exception e) {
                throw new NotificationApiException("카드 결제 요청 중 오류가 발생했습니다: " + e.getMessage());
            }


            CardNotification cardPayment = CardNotification.builder()
                    .cardNumber(paymentInfo.getCardNumber())
                    .cardPassword(paymentInfo.getCardPassword())
                    .cardExpiration(paymentInfo.getExpirationDate())
                    .birthDate(paymentInfo.getBirthDate())
                    .cardType((String) response.get("card_name"))
                    .paidAmount(requestDto.getPaidAmount())
                    .impUid((String) response.get("imp_uid"))
                    .receiptUrl((String) response.get("receipt_url"))
                    .pgProvider((String) response.get("pg_provider"))
                    .pgTid((String) response.get("pg_tid"))
                    .build();

            cardPayment.assignOrder(order);
            cardPayment.assignUser(user);

            if ("success".equals(response.get("status"))) {
                cardPayment.updateStatus(NotificationStatus.PAID);
                cardPayment.updateSuccessStatus(true);
            }

            CardNotification savedPayment = (CardNotification) paymentRepository.save(cardPayment);
            log.info("카드 결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
                    order.getId(), savedPayment.getId(), savedPayment.getStatus());


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
