package com.fream.back.domain.notification.entity;

public enum NotificationStatus {
    PENDING,
    PAID,
    REFUND_REQUESTED,
    REFUNDED,
    FAILED;

    public boolean canTransitionTo(NotificationStatus newStatus) {
        switch (this) {
            case PENDING:
                return newStatus == PAID;
            case PAID:
                return newStatus == REFUND_REQUESTED || newStatus == REFUNDED;
            case REFUND_REQUESTED:
                return newStatus == REFUNDED;
            default:
                return false;
        }
    }
